outcomes.sql:
SELECT COUNT(*) AS total_trips
FROM multimodal_trips_canada
WHERE city = 'Toronto' AND LOWER(mode) LIKE '%public%';

SELECT country, AVG(price) AS average_price
FROM eco_materials
GROUP BY country;

SELECT COUNT(*) AS total_subscribers
FROM broadband_subscribers
WHERE subscriber_location = 'Urban';

SELECT operation_name, environmental_impact
FROM mining_operations
WHERE environmental_impact > (SELECT AVG(environmental_impact) FROM mining_operations);

SELECT region, AVG(sequestration / area) AS avg_sequestration_per_hectare
FROM carbon_sequestration
GROUP BY region;

SELECT Region, SUM(NumLibraries) AS TotalLibraries
FROM Libraries
GROUP BY Region;

SELECT Country, COUNT(DISTINCT GameGenre) AS UniqueGenres
FROM Players
GROUP BY Country;

SELECT department, COUNT(*) AS total_workers
FROM workers
GROUP BY department;

SELECT AVG(Water_Consumption) AS Average_Water_Consumption
FROM Household_Water_Usage
WHERE City = 'Mumbai' AND Year IN (2018, 2019);

SELECT 'school' AS type, name, needs_repair FROM schools WHERE country = 'Colombia'
UNION ALL
SELECT 'hospital' AS type, name, needs_repair FROM hospitals WHERE country = 'Colombia';

SELECT category, SUM(price * quantity) AS total_revenue, COUNT(*) AS total_events
FROM revenue
GROUP BY category;

SELECT name, AVG(crime_count * 1.0 / population) AS avg_crime_rate_per_capita
FROM neighborhoods
GROUP BY name;

SELECT PolicyState, COUNT(*) AS total_policies
FROM Policies
GROUP BY PolicyState;

SELECT location, SUM(population) AS total_animals
FROM animal_population
GROUP BY location;

SELECT COUNT(*) AS landfill_count, SUM(capacity_cubic_yards) AS total_capacity
FROM landfills
WHERE location = 'Texas';

SELECT branch, SUM(personnel_count) AS total_personnel
FROM MilitaryPersonnel
GROUP BY branch;

SELECT Disability_Type, COUNT(DISTINCT Student_ID) AS student_count
FROM Disability_Accommodations
GROUP BY Disability_Type;

SELECT industry, union_status, SUM(num_employees) AS total_employees
FROM employees
GROUP BY industry, union_status;

SELECT 100.0 * SUM(CASE WHEN attendee_age < 12 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM AgeDistribution
WHERE event_name = 'Family Day';
